  (4742, 12, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary school in Hereford","organisation":null,"detail":"He left school at 16 with no qualifications.","source":{"title":"Hansard: Global Britain, 30 January 2020 (maiden speech)","url":"https://hansard.parliament.uk/Commons/2020-01-30/debates/33EA2EAC-BA44-490B-93D0-11799618B342/GlobalBritain"}},{"phase":"education","start":null,"end":null,"title":"MSc in Security and Risk Management","organisation":null,"detail":"He obtained the degree after leaving the army and moving into the defence and security industry.","source":{"title":"About Me | Stuart Anderson MP","url":"https://www.stuartanderson.org.uk/about-me"}},{"phase":"career","start":null,"end":null,"title":"Farm hand","organisation":null,"detail":"He worked as a farm hand in rural Herefordshire before joining the army.","source":{"title":"About Me | Stuart Anderson MP","url":"https://www.stuartanderson.org.uk/about-me"}},{"phase":"career","start":null,"end":null,"title":"Rifleman","organisation":"Royal Green Jackets","detail":"He served in Northern Ireland, Bosnia and Kosovo and left the army eight years after joining.","source":{"title":"BBC News: The MP who was shot in the foot as a teen","url":"https://www.bbc.co.uk/news/articles/cn52k006pd0o"}},{"phase":"career","start":null,"end":null,"title":"Security and defence industry","organisation":null,"detail":"After leaving the Royal Green Jackets he went into the security and defence industry.","source":{"title":"BBC News: The MP who was shot in the foot as a teen","url":"https://www.bbc.co.uk/news/articles/cn52k006pd0o"}},{"phase":"career","start":"2005","end":"2013","title":"Director","organisation":"Anubis Associates","detail":"He was one of three directors who set up the security training firm in 2005, which collapsed in 2013.","source":{"title":"The Guardian: Tory candidate got illegal dividend from firm that went bust","url":"https://www.theguardian.com/politics/2019/nov/22/tory-can